  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}

passes.source:
precision highp float;

uniform vec2 iResolution;
uniform float iTime;
uniform vec4 iMouse;

// Bound with feedback: the frame this buffer drew last tick.
uniform sampler2D iChannel0;

uniform float u_fade;
uniform float u_speed;
uniform vec3 u_ink;
uniform bool u_reset;

void main() {
  vec2 uv = gl_FragCoord.xy / iResolution;
  vec4 last = texture2D(iChannel0, uv);

  // A buffer starts out (and restarts after a resize) all zeros, alpha included.
  // Every texel this pass writes has alpha 1, so alpha 0 means "never drawn": start clean.
  if (u_reset || last.a < 0.5) last = vec4(0.0, 0.0, 0.0, 1.0);

  // The brush follows a Lissajous curve, or the pointer while it is pressed.
  vec2 p = (gl_FragCoord.xy - 0.5 * iResolution) / iResolution.y;
  float t = iTime * u_speed;
  vec2 brush = 0.35 * vec2(sin(t * 1.3), sin(t * 2.1));
  if (iMouse.z > 0.0) brush = (iMouse.xy - 0.5 * iResolution) / iResolution.y;
  float ink = smoothstep(0.05, 0.0, length(p - brush));

  // Fade what was there, add what is new: the trail is the history of the brush.
  vec3 color = last.rgb * u_fade + u_ink * ink;
  gl_FragColor = vec4(min(color, vec3(4.0)), 1.0);
}

precision highp float;

uniform vec2 iResolution;

// Buffer A, without feedback: the frame it drew this tick.
uniform sampler2D iChannel0;

uniform vec3 u_background;

void main() {
  vec2 uv = gl_FragCoord.xy / iResolution;
  vec3 trail = texture2D(iChannel0, uv).rgb;
  // The buffer stores unbounded light; compress it for display.
  gl_FragColor = vec4(u_background + trail / (1.0 + trail), 1.0);
}
